  ('ai:ai-batch-09:fa76a65f5997','C2'::public.cefr_level,'vocabulary','The company''s fortunes have ___ over the decades.',array['waxen and waned','waned and waxing','waxed and waned','waxed and wavered']::text[],'C','''Wax and wane'' = increase and decrease.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
