  ('ai:ai-batch-09:37ce3167ec27','C2'::public.cefr_level,'vocabulary','He had a ___ escape from the burning building.',array['hair-raising','hairline','hair''s-breadth','hairy']::text[],'C','A hair''s-breadth escape = very narrow.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:6e048be33064','C2'::public.cefr_level,'vocabulary','The proposal was rejected out of ___.',array['hand','turn','place','mind']::text[],'A','''Out of hand'' = immediately, without consideration.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:8fd036615666','C2'::public.cefr_level,'vocabulary','The two companies are at ___ over the contract.',array['loggers','loggerheads','headlocks','logjam']::text[],'B','At loggerheads = in strong disagreement.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:eecf78379afc','C2'::public.cefr_level,'vocabulary','The scheme proved to be a ___ — it achieved nothing.',array['white elephant','dark horse','red herring','white lie']::text[],'A','A white elephant = costly and useless.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:843f35a50281','C2'::public.cefr_level,'vocabulary','The detail about the car turned out to be a red ___.',array['haring','hearing','herring','heron']::text[],'C','A red herring = misleading clue.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:87dfb48fdd42','C2'::public.cefr_level,'vocabulary','She was the ___ horse of the election, winning unexpectedly.',array['black','white','dark','grey']::text[],'C','A dark horse = an unexpected winner.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
