  ('ai:ai-batch-09:c054b5e7502a','C2'::public.cefr_level,'vocabulary','The plan was ___ in the bud.',array['nipped','napped','nibbled','knocked']::text[],'A','''Nip in the bud'' = stop at an early stage.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:7e27591cc466','C2'::public.cefr_level,'vocabulary','They decided to bury the ___ and work together.',array['hatch','hammer','axe up','hatchet']::text[],'D','''Bury the hatchet'' = end a quarrel.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:4af07966d430','C2'::public.cefr_level,'vocabulary','The minister was accused of ___ the issue.',array['fumbling','funding','fading','fudging']::text[],'D','To fudge = avoid dealing with clearly.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:c2547b7ccd9e','C2'::public.cefr_level,'vocabulary','The company has been ___ by scandal.',array['engaged','enrolled','engulfed','engraved']::text[],'C','Engulfed = completely overwhelmed.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:454a55fcdf40','C2'::public.cefr_level,'vocabulary','There''s a ___ line between confidence and arrogance.',array['fine','slim up','thin up','narrow up']::text[],'A','''A fine line''.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:b61842aeed2f','C2'::public.cefr_level,'vocabulary','The essay was ___ with errors.',array['littered','fluttered','lettered','littering']::text[],'A','Littered with = containing many.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:39752050b633','C2'::public.cefr_level,'vocabulary','The film offers a ___ portrayal of addiction.',array['unflinching','unflattering up','unfailing','unfledged']::text[],'A','Unflinching = not avoiding unpleasant truths.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:d11b87b4e0fe','C2'::public.cefr_level,'vocabulary','The reforms were ___ through parliament.',array['rushed','ruched','rusted','rustled']::text[],'A','Rushed through = passed hastily.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:196f5843fb27','C2'::public.cefr_level,'vocabulary','He made a ___ apology.',array['perfunctory','perpetual','perforated','peremptory']::text[],'A','Perfunctory = done without real interest.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:08e7396cb5c2','C2'::public.cefr_level,'vocabulary','The manager issued a ___ order to leave immediately.',array['permissive','peripheral','peremptory','perfunctory']::text[],'C','Peremptory = insisting on immediate obedience.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:e8b3a3b8b2e0','C2'::public.cefr_level,'vocabulary','The rules are applied in an ___ manner.',array['arbiter','arboreal','arbitrated','arbitrary']::text[],'D','Arbitrary = not based on reason or system.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:64ca44f06c10','C2'::public.cefr_level,'vocabulary','She has a ___ understanding of the law.',array['nuanceless','nuanced','nuance up','new-anced']::text[],'B','Nuanced = showing subtle differences.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:eeee91642b6d','C2'::public.cefr_level,'vocabulary','The CEO''s ___ led to the company''s downfall.',array['hubbub','hybrid','hubris','humus']::text[],'C','Hubris = excessive pride and self-confidence.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
  ('ai:ai-batch-09:46900920ea86','C2'::public.cefr_level,'reading','In what spirit did Michael Young coin ''meritocracy''?',array['as a political slogan','as an ideal to aim for','as a scientific term','as a warning']::text[],'D','''...not as an ideal but as a warning.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The term ''meritocracy'' was coined in 1958 by the sociologist Michael Young, not as an ideal but as a warning. In his satirical book, a society that allocates positions purely on the basis of measured intelligence and effort becomes rigidly stratified, with the successful convinced that they deserve their advantages and the unsuccessful deprived of any consolation. Young was dismayed when politicians later adopted the word approvingly, apparently oblivious to its original irony. Contemporary critics echo his concern, arguing that the rhetoric of merit can obscure the role of inherited advantage and luck.',null,null,null,'practice'),
  ('ai:ai-batch-09:c9ca270a692c','C2'::public.cefr_level,'reading','What happens in the society Young describes?',array['Everyone becomes equal.','It becomes rigidly stratified and the successful feel entitled.','The unsuccessful rule the country.','Intelligence becomes irrelevant.']::text[],'B','''...becomes rigidly stratified, with the successful convinced that they deserve their advantages.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The term ''meritocracy'' was coined in 1958 by the sociologist Michael Young, not as an ideal but as a warning. In his satirical book, a society that allocates positions purely on the basis of measured intelligence and effort becomes rigidly stratified, with the successful convinced that they deserve their advantages and the unsuccessful deprived of any consolation. Young was dismayed when politicians later adopted the word approvingly, apparently oblivious to its original irony. Contemporary critics echo his concern, arguing that the rhetoric of merit can obscure the role of inherited advantage and luck.',null,null,null,'practice'),
  ('ai:ai-batch-09:c38748bd1e81','C2'::public.cefr_level,'reading','Why was Young dismayed?',array['Nobody read his book.','The word was misspelt.','Politicians used the word approvingly, missing its irony.','His book was banned.']::text[],'C','''...politicians later adopted the word approvingly, apparently oblivious to its original irony.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The term ''meritocracy'' was coined in 1958 by the sociologist Michael Young, not as an ideal but as a warning. In his satirical book, a society that allocates positions purely on the basis of measured intelligence and effort becomes rigidly stratified, with the successful convinced that they deserve their advantages and the unsuccessful deprived of any consolation. Young was dismayed when politicians later adopted the word approvingly, apparently oblivious to its original irony. Contemporary critics echo his concern, arguing that the rhetoric of merit can obscure the role of inherited advantage and luck.',null,null,null,'practice'),
  ('ai:ai-batch-09:45b96d3e1f74','C2'::public.cefr_level,'reading','What do contemporary critics argue?',array['Merit should be measured more often.','Intelligence tests are fair.','Luck plays no role in success.','The language of merit can hide inherited advantage and luck.']::text[],'D','''...the rhetoric of merit can obscure the role of inherited advantage and luck.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The term ''meritocracy'' was coined in 1958 by the sociologist Michael Young, not as an ideal but as a warning. In his satirical book, a society that allocates positions purely on the basis of measured intelligence and effort becomes rigidly stratified, with the successful convinced that they deserve their advantages and the unsuccessful deprived of any consolation. Young was dismayed when politicians later adopted the word approvingly, apparently oblivious to its original irony. Contemporary critics echo his concern, arguing that the rhetoric of merit can obscure the role of inherited advantage and luck.',null,null,null,'practice'),
  ('ai:ai-batch-09:baf256787410','C2'::public.cefr_level,'reading','What dilemma do poetry translators face?',array['choosing which language to translate into','deciding the length','finding a publisher','choosing between literal meaning and the music of the original']::text[],'D','''...whether fidelity to literal meaning or to the music and feeling of the original should take precedence.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Poetry is often said to be what gets lost in translation. Yet some of the most celebrated poems in English are themselves translations, and translators have long debated whether fidelity to literal meaning or to the music and feeling of the original should take precedence. A literal rendering may preserve sense while destroying rhythm; a freer version may capture the spirit at the cost of accuracy. Some translators resolve the dilemma by publishing parallel texts, inviting readers to triangulate between the original and its interpretation.',null,null,null,'practice'),
  ('ai:ai-batch-09:8400a2fe98e2','C2'::public.cefr_level,'reading','What may a literal translation lose?',array['the author''s name','meaning','rhythm','accuracy']::text[],'C','''A literal rendering may preserve sense while destroying rhythm.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Poetry is often said to be what gets lost in translation. Yet some of the most celebrated poems in English are themselves translations, and translators have long debated whether fidelity to literal meaning or to the music and feeling of the original should take precedence. A literal rendering may preserve sense while destroying rhythm; a freer version may capture the spirit at the cost of accuracy. Some translators resolve the dilemma by publishing parallel texts, inviting readers to triangulate between the original and its interpretation.',null,null,null,'practice'),
  ('ai:ai-batch-09:424e0f272de4','C2'::public.cefr_level,'reading','How do parallel texts help readers?',array['They can compare the original with the translation.','They make books shorter.','They remove the need to translate.','They add illustrations.']::text[],'A','''...inviting readers to triangulate between the original and its interpretation.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Poetry is often said to be what gets lost in translation. Yet some of the most celebrated poems in English are themselves translations, and translators have long debated whether fidelity to literal meaning or to the music and feeling of the original should take precedence. A literal rendering may preserve sense while destroying rhythm; a freer version may capture the spirit at the cost of accuracy. Some translators resolve the dilemma by publishing parallel texts, inviting readers to triangulate between the original and its interpretation.',null,null,null,'practice'),
  ('ai:ai-batch-09:3c76282b56cb','C2'::public.cefr_level,'reading','What point does the text make about famous English poems?',array['All are untranslatable.','They are written in Latin.','None have been translated.','Some are themselves translations.']::text[],'D','''...some of the most celebrated poems in English are themselves translations.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Poetry is often said to be what gets lost in translation. Yet some of the most celebrated poems in English are themselves translations, and translators have long debated whether fidelity to literal meaning or to the music and feeling of the original should take precedence. A literal rendering may preserve sense while destroying rhythm; a freer version may capture the spirit at the cost of accuracy. Some translators resolve the dilemma by publishing parallel texts, inviting readers to triangulate between the original and its interpretation.',null,null,null,'practice'),
  ('ai:ai-batch-09:a072bbbf0188','C2'::public.cefr_level,'reading','According to critics, what is privacy really about?',array['hiding wrongdoing','keeping secrets from friends','preserving space to explore and change without scrutiny','avoiding taxes']::text[],'C','''...preserving the space in which people can explore ideas, form relationships and change their minds without scrutiny.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The claim that ''if you have nothing to hide, you have nothing to fear'' is frequently invoked to justify surveillance. Critics contend that it rests on a misunderstanding of privacy, which is not merely about concealing wrongdoing but about preserving the space in which people can explore ideas, form relationships and change their minds without scrutiny. Moreover, what counts as ''something to hide'' is determined not by the individual but by whoever controls the data — and may change as governments and norms change.',null,null,null,'practice'),
  ('ai:ai-batch-09:1dfd8b240ec7','C2'::public.cefr_level,'reading','Who decides what counts as ''something to hide''?',array['nobody','whoever controls the data','the courts alone','the individual']::text[],'B','''...is determined not by the individual but by whoever controls the data.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The claim that ''if you have nothing to hide, you have nothing to fear'' is frequently invoked to justify surveillance. Critics contend that it rests on a misunderstanding of privacy, which is not merely about concealing wrongdoing but about preserving the space in which people can explore ideas, form relationships and change their minds without scrutiny. Moreover, what counts as ''something to hide'' is determined not by the individual but by whoever controls the data — and may change as governments and norms change.',null,null,null,'practice'),
  ('ai:ai-batch-09:e86694640117','C2'::public.cefr_level,'reading','What is the writer''s attitude to the ''nothing to hide'' argument?',array['critical','amused','neutral','supportive']::text[],'A','The text presents critics'' objections to the claim.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The claim that ''if you have nothing to hide, you have nothing to fear'' is frequently invoked to justify surveillance. Critics contend that it rests on a misunderstanding of privacy, which is not merely about concealing wrongdoing but about preserving the space in which people can explore ideas, form relationships and change their minds without scrutiny. Moreover, what counts as ''something to hide'' is determined not by the individual but by whoever controls the data — and may change as governments and norms change.',null,null,null,'practice'),
  ('ai:ai-batch-09:e5300ceabadd','C2'::public.cefr_level,'reading','Why might what counts as ''something to hide'' change?',array['Technology improves.','People forget.','Governments and social norms change.','Laws never change.']::text[],'C','''...and may change as governments and norms change.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The claim that ''if you have nothing to hide, you have nothing to fear'' is frequently invoked to justify surveillance. Critics contend that it rests on a misunderstanding of privacy, which is not merely about concealing wrongdoing but about preserving the space in which people can explore ideas, form relationships and change their minds without scrutiny. Moreover, what counts as ''something to hide'' is determined not by the individual but by whoever controls the data — and may change as governments and norms change.',null,null,null,'practice'),
  ('ai:ai-batch-09:6848fb37329c','C2'::public.cefr_level,'reading','Why is expert intuition reliable in chess or firefighting?',array['There are fewer experts.','These experts are more intelligent.','There is rapid feedback to learn from.','The tasks are simple.']::text[],'C','''...practitioners have had countless opportunities to learn which cues predict which outcomes.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','In fields characterised by rapid feedback, such as chess or firefighting, expert intuition can be remarkably reliable, because practitioners have had countless opportunities to learn which cues predict which outcomes. In contrast, in domains where feedback is delayed or ambiguous, such as long-term political forecasting, the confidence of experts often exceeds their accuracy. Psychologists therefore advise distinguishing between expertise grounded in a regular, learnable environment and mere familiarity with a subject.',null,null,null,'practice'),
  ('ai:ai-batch-09:af1688e234c5','C2'::public.cefr_level,'reading','What problem arises in long-term political forecasting?',array['Experts refuse to make predictions.','Experts'' confidence exceeds their accuracy.','Feedback is immediate.','There are no experts.']::text[],'B','''...the confidence of experts often exceeds their accuracy.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','In fields characterised by rapid feedback, such as chess or firefighting, expert intuition can be remarkably reliable, because practitioners have had countless opportunities to learn which cues predict which outcomes. In contrast, in domains where feedback is delayed or ambiguous, such as long-term political forecasting, the confidence of experts often exceeds their accuracy. Psychologists therefore advise distinguishing between expertise grounded in a regular, learnable environment and mere familiarity with a subject.',null,null,null,'practice'),
  ('ai:ai-batch-09:24af1a9deb8c','C2'::public.cefr_level,'reading','What do psychologists advise?',array['Always trust experts.','Distinguish real expertise from mere familiarity.','Never trust intuition.','Avoid fast feedback.']::text[],'B','''...distinguishing between expertise grounded in a regular, learnable environment and mere familiarity.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','In fields characterised by rapid feedback, such as chess or firefighting, expert intuition can be remarkably reliable, because practitioners have had countless opportunities to learn which cues predict which outcomes. In contrast, in domains where feedback is delayed or ambiguous, such as long-term political forecasting, the confidence of experts often exceeds their accuracy. Psychologists therefore advise distinguishing between expertise grounded in a regular, learnable environment and mere familiarity with a subject.',null,null,null,'practice'),
  ('ai:ai-batch-09:f89ba4b32171','C2'::public.cefr_level,'reading','What did ruins symbolise for Romantic artists?',array['religious certainty','the transience of human ambition','technological progress','the power of kings']::text[],'B','''...meditations on the transience of human ambition.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The Romantic fascination with ruins reflected more than an appreciation of picturesque decay. For many eighteenth- and nineteenth-century writers and painters, crumbling abbeys and castles served as meditations on the transience of human ambition and the inevitable triumph of nature over culture. Some wealthy landowners went so far as to construct artificial ruins, or ''follies'', on their estates — an apparent paradox that reveals how far the aesthetic of melancholy had become a fashionable commodity.',null,null,null,'practice'),
  ('ai:ai-batch-09:84c9d52598cc','C2'::public.cefr_level,'reading','What were ''follies''?',array['artificial ruins built on estates','foolish people','theatres','real medieval castles']::text[],'A','''...construct artificial ruins, or ''follies'', on their estates.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The Romantic fascination with ruins reflected more than an appreciation of picturesque decay. For many eighteenth- and nineteenth-century writers and painters, crumbling abbeys and castles served as meditations on the transience of human ambition and the inevitable triumph of nature over culture. Some wealthy landowners went so far as to construct artificial ruins, or ''follies'', on their estates — an apparent paradox that reveals how far the aesthetic of melancholy had become a fashionable commodity.',null,null,null,'practice'),
  ('ai:ai-batch-09:e929ef0ad38d','C2'::public.cefr_level,'reading','What does the building of follies reveal, according to the text?',array['that melancholy had become fashionable and marketable','that landowners were poor','that nature had won','that ruins were dangerous']::text[],'A','''...how far the aesthetic of melancholy had become a fashionable commodity.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The Romantic fascination with ruins reflected more than an appreciation of picturesque decay. For many eighteenth- and nineteenth-century writers and painters, crumbling abbeys and castles served as meditations on the transience of human ambition and the inevitable triumph of nature over culture. Some wealthy landowners went so far as to construct artificial ruins, or ''follies'', on their estates — an apparent paradox that reveals how far the aesthetic of melancholy had become a fashionable commodity.',null,null,null,'practice'),
  ('ai:ai-batch-09:55c0cb5a6eb8','C2'::public.cefr_level,'reading','What, according to the text, has become the scarce resource?',array['money','technology','attention','information']::text[],'C','''...attention has become the scarce resource.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','In an economy saturated with information, attention has become the scarce resource. Platforms compete not primarily for users'' money but for their time, and many design features — infinite scrolling, autoplay, variable rewards — are calibrated to maximise engagement. Critics argue that framing the resulting distraction as a failure of individual self-control obscures the asymmetry of power between users and companies that employ teams of behavioural scientists. Proposed remedies range from regulation of design practices to the cultivation of what some call ''digital sovereignty''.',null,null,null,'practice'),
  ('ai:ai-batch-09:663ef75bcda2','C2'::public.cefr_level,'reading','What is the purpose of features like autoplay?',array['to reduce screen time','to protect children','to save battery','to maximise engagement']::text[],'D','''...calibrated to maximise engagement.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','In an economy saturated with information, attention has become the scarce resource. Platforms compete not primarily for users'' money but for their time, and many design features — infinite scrolling, autoplay, variable rewards — are calibrated to maximise engagement. Critics argue that framing the resulting distraction as a failure of individual self-control obscures the asymmetry of power between users and companies that employ teams of behavioural scientists. Proposed remedies range from regulation of design practices to the cultivation of what some call ''digital sovereignty''.',null,null,null,'practice'),
  ('ai:ai-batch-09:8f10312c50d9','C2'::public.cefr_level,'reading','What asymmetry do critics highlight?',array['Readers versus writers','Users versus companies employing behavioural scientists','Old versus young users','Rich versus poor countries']::text[],'B','''...the asymmetry of power between users and companies that employ teams of behavioural scientists.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','In an economy saturated with information, attention has become the scarce resource. Platforms compete not primarily for users'' money but for their time, and many design features — infinite scrolling, autoplay, variable rewards — are calibrated to maximise engagement. Critics argue that framing the resulting distraction as a failure of individual self-control obscures the asymmetry of power between users and companies that employ teams of behavioural scientists. Proposed remedies range from regulation of design practices to the cultivation of what some call ''digital sovereignty''.',null,null,null,'practice'),
  ('ai:ai-batch-09:4dbe8128c94a','C2'::public.cefr_level,'reading','How do descriptive linguists differ from prescriptive grammarians?',array['They teach only formal English.','They reject all grammar.','They record actual usage rather than prescribe rules.','They invent new words.']::text[],'C','''...descriptive linguists set out to record how it is actually used.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Prescriptive grammarians lay down rules about how language ought to be used, while descriptive linguists set out to record how it is actually used. The distinction is often caricatured as a clash between pedants and relativists, but most linguists acknowledge that standard varieties serve real functions in education and formal communication. Their objection is rather to the presentation of social conventions as timeless logical laws, and to the stigmatisation of speakers of non-standard varieties as careless or unintelligent.',null,null,null,'practice'),
  ('ai:ai-batch-09:b8af626cf3a8','C2'::public.cefr_level,'reading','What do most linguists acknowledge?',array['Standard varieties serve real functions.','Non-standard speech is careless.','Grammar rules are logical laws.','Prescription is always right.']::text[],'A','''...most linguists acknowledge that standard varieties serve real functions in education and formal communication.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Prescriptive grammarians lay down rules about how language ought to be used, while descriptive linguists set out to record how it is actually used. The distinction is often caricatured as a clash between pedants and relativists, but most linguists acknowledge that standard varieties serve real functions in education and formal communication. Their objection is rather to the presentation of social conventions as timeless logical laws, and to the stigmatisation of speakers of non-standard varieties as careless or unintelligent.',null,null,null,'practice'),
  ('ai:ai-batch-09:92c89180d807','C2'::public.cefr_level,'reading','What do linguists object to?',array['recording usage','teaching standard English','using dictionaries','presenting social conventions as logical laws']::text[],'D','''Their objection is rather to the presentation of social conventions as timeless logical laws.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Prescriptive grammarians lay down rules about how language ought to be used, while descriptive linguists set out to record how it is actually used. The distinction is often caricatured as a clash between pedants and relativists, but most linguists acknowledge that standard varieties serve real functions in education and formal communication. Their objection is rather to the presentation of social conventions as timeless logical laws, and to the stigmatisation of speakers of non-standard varieties as careless or unintelligent.',null,null,null,'practice'),
  ('ai:ai-batch-09:4095ff9abc6e','C2'::public.cefr_level,'reading','What was often conditional about Victorian charity?',array['It was always anonymous.','Aid depended on judgements about who was ''deserving''.','It was paid by the state.','It was only given to the rich.']::text[],'B','''...aid was distributed according to judgements about the ''deserving'' and ''undeserving'' poor.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Victorian philanthropy is frequently remembered through its grand public institutions — libraries, museums and model housing estates. Yet historians note that much charitable activity at the time was conditional: aid was distributed according to judgements about the ''deserving'' and ''undeserving'' poor, and recipients were often subjected to moral supervision. This legacy, they argue, continues to shape debates about welfare, in which the question of whether assistance should be universal or targeted remains contested.',null,null,null,'practice'),
  ('ai:ai-batch-09:97c33c2dfff9','C2'::public.cefr_level,'reading','How does this legacy affect debates today?',array['It created museums.','It led to the end of welfare.','It has no influence.','It shapes arguments about universal versus targeted welfare.']::text[],'D','''...whether assistance should be universal or targeted remains contested.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Victorian philanthropy is frequently remembered through its grand public institutions — libraries, museums and model housing estates. Yet historians note that much charitable activity at the time was conditional: aid was distributed according to judgements about the ''deserving'' and ''undeserving'' poor, and recipients were often subjected to moral supervision. This legacy, they argue, continues to shape debates about welfare, in which the question of whether assistance should be universal or targeted remains contested.',null,null,null,'practice'),
  ('ai:ai-batch-09:d5c5115b2a85','C2'::public.cefr_level,'reading','How do historians of science describe research?',array['collaborative, incremental and messy','purely theoretical','always successful','sudden and individual']::text[],'A','''...the collaborative, incremental and often messy nature of research.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Popular accounts of science often portray discovery as a sudden flash of insight by a lone genius. Historians of science, however, emphasise the collaborative, incremental and often messy nature of research, in which failed experiments, disputes over priority and the slow accumulation of data play decisive roles. The ''eureka'' narrative, they suggest, persists partly because it makes for a compelling story, but it can mislead students into believing that setbacks indicate a lack of talent rather than an ordinary feature of scientific work.',null,null,null,'practice'),
  ('ai:ai-batch-09:dcf705cf9d68','C2'::public.cefr_level,'reading','Why does the ''eureka'' narrative persist?',array['Scientists prefer it.','It is accurate.','It makes a compelling story.','It is taught by law.']::text[],'C','''...it persists partly because it makes for a compelling story.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Popular accounts of science often portray discovery as a sudden flash of insight by a lone genius. Historians of science, however, emphasise the collaborative, incremental and often messy nature of research, in which failed experiments, disputes over priority and the slow accumulation of data play decisive roles. The ''eureka'' narrative, they suggest, persists partly because it makes for a compelling story, but it can mislead students into believing that setbacks indicate a lack of talent rather than an ordinary feature of scientific work.',null,null,null,'practice'),
  ('ai:ai-batch-09:dd375631dad5','C2'::public.cefr_level,'reading','What harm can the ''eureka'' narrative do to students?',array['They become overconfident.','They avoid collaboration entirely.','They stop reading.','They may think setbacks mean a lack of talent.']::text[],'D','''...believing that setbacks indicate a lack of talent rather than an ordinary feature of scientific work.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Popular accounts of science often portray discovery as a sudden flash of insight by a lone genius. Historians of science, however, emphasise the collaborative, incremental and often messy nature of research, in which failed experiments, disputes over priority and the slow accumulation of data play decisive roles. The ''eureka'' narrative, they suggest, persists partly because it makes for a compelling story, but it can mislead students into believing that setbacks indicate a lack of talent rather than an ordinary feature of scientific work.',null,null,null,'practice'),
  ('ai:ai-batch-09:b454bce6ad50','C2'::public.cefr_level,'reading','Why are street names ''rarely neutral''?',array['They describe the street''s shape.','They are chosen randomly.','They encode a version of history.','They change every year.']::text[],'C','''They commemorate particular figures and events, and... encode a version of history.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Street names are rarely neutral. They commemorate particular figures and events, and in doing so encode a version of history into the fabric of everyday life. Periods of political upheaval are frequently accompanied by waves of renaming, as new regimes seek to erase the symbols of their predecessors. Such changes can provoke fierce resistance, not only for ideological reasons but because names accumulate personal associations: for many residents, the old name is bound up with memories that have little to do with the person it honoured.',null,null,null,'practice'),
  ('ai:ai-batch-09:d6b24a57fa0a','C2'::public.cefr_level,'reading','Why do renamings often follow political upheaval?',array['New regimes erase their predecessors'' symbols.','Old names are too long.','Residents request it.','Maps need updating.']::text[],'A','''...as new regimes seek to erase the symbols of their predecessors.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Street names are rarely neutral. They commemorate particular figures and events, and in doing so encode a version of history into the fabric of everyday life. Periods of political upheaval are frequently accompanied by waves of renaming, as new regimes seek to erase the symbols of their predecessors. Such changes can provoke fierce resistance, not only for ideological reasons but because names accumulate personal associations: for many residents, the old name is bound up with memories that have little to do with the person it honoured.',null,null,null,'practice'),
  ('ai:ai-batch-09:129796f634e7','C2'::public.cefr_level,'reading','Besides ideology, why do residents resist renaming?',array['New names are hard to spell.','They dislike change of any kind.','Old names carry personal memories.','It costs them money directly.']::text[],'C','''...names accumulate personal associations.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Street names are rarely neutral. They commemorate particular figures and events, and in doing so encode a version of history into the fabric of everyday life. Periods of political upheaval are frequently accompanied by waves of renaming, as new regimes seek to erase the symbols of their predecessors. Such changes can provoke fierce resistance, not only for ideological reasons but because names accumulate personal associations: for many residents, the old name is bound up with memories that have little to do with the person it honoured.',null,null,null,'practice'),
  ('ai:ai-batch-09:b131af26f269','C2'::public.cefr_level,'reading','How was nostalgia once viewed?',array['as a form of happiness','as a political tool','as a sign of wisdom','as a medical condition']::text[],'D','''Nostalgia was once classified as a medical condition.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Nostalgia was once classified as a medical condition, a form of melancholy afflicting soldiers and emigrants far from home. Contemporary psychologists take a more benign view: research suggests that nostalgic reflection can bolster self-esteem, foster a sense of social connectedness and counteract loneliness. Nonetheless, nostalgia has a political dimension that is less benign, as appeals to an idealised past can be mobilised to resist change or to exclude those who do not fit a particular vision of national identity.',null,null,null,'practice'),
  ('ai:ai-batch-09:6aec3583b69f','C2'::public.cefr_level,'reading','What benefits do contemporary psychologists attribute to nostalgia?',array['longer life','improved eyesight','higher self-esteem and social connectedness','better memory']::text[],'C','''...can bolster self-esteem, foster a sense of social connectedness and counteract loneliness.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Nostalgia was once classified as a medical condition, a form of melancholy afflicting soldiers and emigrants far from home. Contemporary psychologists take a more benign view: research suggests that nostalgic reflection can bolster self-esteem, foster a sense of social connectedness and counteract loneliness. Nonetheless, nostalgia has a political dimension that is less benign, as appeals to an idealised past can be mobilised to resist change or to exclude those who do not fit a particular vision of national identity.',null,null,null,'practice'),
  ('ai:ai-batch-09:d45d4b0f7d9e','C2'::public.cefr_level,'reading','What is the ''less benign'' side of nostalgia?',array['its cost','its effect on sleep','its use in politics to resist change or exclude people','its link to illness']::text[],'C','''...appeals to an idealised past can be mobilised to resist change or to exclude...''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Nostalgia was once classified as a medical condition, a form of melancholy afflicting soldiers and emigrants far from home. Contemporary psychologists take a more benign view: research suggests that nostalgic reflection can bolster self-esteem, foster a sense of social connectedness and counteract loneliness. Nonetheless, nostalgia has a political dimension that is less benign, as appeals to an idealised past can be mobilised to resist change or to exclude those who do not fit a particular vision of national identity.',null,null,null,'practice'),
  ('ai:ai-batch-09:6c3b2b7c5a67','C2'::public.cefr_level,'reading','How is gentrification often portrayed?',array['neutrally','in stark, opposing terms','as purely economic','as irrelevant']::text[],'B','''...portrayed in stark terms, either as revitalisation or as displacement.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Gentrification — the influx of wealthier residents into previously working-class neighbourhoods — is frequently portrayed in stark terms, either as revitalisation or as displacement. Empirical studies paint a more ambiguous picture. Long-standing residents who manage to stay may benefit from improved services and safety, yet rising rents can force out tenants, and the closure of familiar shops and gathering places can erode the social fabric even for those who remain. The policy challenge lies in capturing the benefits of investment without dispersing existing communities.',null,null,null,'practice'),
  ('ai:ai-batch-09:e7075fe93088','C2'::public.cefr_level,'reading','How can gentrification harm even residents who stay?',array['Services get worse.','It can erode the social fabric.','They lose their jobs.','Their rents always fall.']::text[],'B','''...the closure of familiar shops and gathering places can erode the social fabric even for those who remain.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Gentrification — the influx of wealthier residents into previously working-class neighbourhoods — is frequently portrayed in stark terms, either as revitalisation or as displacement. Empirical studies paint a more ambiguous picture. Long-standing residents who manage to stay may benefit from improved services and safety, yet rising rents can force out tenants, and the closure of familiar shops and gathering places can erode the social fabric even for those who remain. The policy challenge lies in capturing the benefits of investment without dispersing existing communities.',null,null,null,'practice'),
  ('ai:ai-batch-09:051fff679440','C2'::public.cefr_level,'reading','What is the policy challenge?',array['gaining the benefits of investment without dispersing communities','stopping all investment','raising rents','building more shops']::text[],'A','''...capturing the benefits of investment without dispersing existing communities.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Gentrification — the influx of wealthier residents into previously working-class neighbourhoods — is frequently portrayed in stark terms, either as revitalisation or as displacement. Empirical studies paint a more ambiguous picture. Long-standing residents who manage to stay may benefit from improved services and safety, yet rising rents can force out tenants, and the closure of familiar shops and gathering places can erode the social fabric even for those who remain. The policy challenge lies in capturing the benefits of investment without dispersing existing communities.',null,null,null,'practice'),
  ('ai:ai-batch-09:c01834158793','C2'::public.cefr_level,'reading','Why is humour hard to translate beyond wordplay?',array['It has no structure.','It is only spoken.','It depends on shared cultural assumptions.','It is always rude.']::text[],'C','''...it depends on shared assumptions about what is incongruous, taboo or absurd.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Humour is notoriously difficult to translate, not merely because of puns and wordplay but because it depends on shared assumptions about what is incongruous, taboo or absurd. A joke that delights one audience may baffle or offend another. Comedians who tour internationally often report rewriting material extensively, retaining the structure of a joke while replacing its cultural references — a process that resembles translation more than mere repetition.',null,null,null,'practice'),
  ('ai:ai-batch-09:0d2345cea95b','C2'::public.cefr_level,'reading','What do touring comedians often do?',array['perform only in English','rewrite material, keeping the structure but changing references','avoid jokes entirely','use interpreters on stage']::text[],'B','''...retaining the structure of a joke while replacing its cultural references.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Humour is notoriously difficult to translate, not merely because of puns and wordplay but because it depends on shared assumptions about what is incongruous, taboo or absurd. A joke that delights one audience may baffle or offend another. Comedians who tour internationally often report rewriting material extensively, retaining the structure of a joke while replacing its cultural references — a process that resembles translation more than mere repetition.',null,null,null,'practice'),
  ('ai:ai-batch-09:a7bc2cad16e5','C2'::public.cefr_level,'reading','What prompted the founding of Slow Food?',array['the opening of a fast-food restaurant in Rome','a food shortage','a cookery competition','a government campaign']::text[],'A','''...partly in protest against the opening of a fast-food restaurant near Rome''s Spanish Steps.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The Slow Food movement, founded in Italy in the 1980s partly in protest against the opening of a fast-food restaurant near Rome''s Spanish Steps, advocates for local, seasonal and traditionally produced food. Its proponents argue that it preserves biodiversity, supports small producers and revives culinary heritage. Detractors, however, characterise it as elitist, pointing out that artisanal products are often beyond the means of low-income households, for whom cheap, convenient food is a necessity rather than a choice.',null,null,null,'practice'),
  ('ai:ai-batch-09:6daded4d70d8','C2'::public.cefr_level,'reading','Why do detractors call Slow Food elitist?',array['It is run by chefs.','It bans restaurants.','It only serves Italian food.','Artisanal food is often unaffordable for poorer households.']::text[],'D','''...artisanal products are often beyond the means of low-income households.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The Slow Food movement, founded in Italy in the 1980s partly in protest against the opening of a fast-food restaurant near Rome''s Spanish Steps, advocates for local, seasonal and traditionally produced food. Its proponents argue that it preserves biodiversity, supports small producers and revives culinary heritage. Detractors, however, characterise it as elitist, pointing out that artisanal products are often beyond the means of low-income households, for whom cheap, convenient food is a necessity rather than a choice.',null,null,null,'practice'),
  ('ai:ai-batch-09:ffe206abae6c','C2'::public.cefr_level,'reading','Which benefit do Slow Food proponents NOT claim?',array['supporting small producers','lower food prices','reviving culinary heritage','preserving biodiversity']::text[],'B','Proponents claim biodiversity, small producers and heritage.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The Slow Food movement, founded in Italy in the 1980s partly in protest against the opening of a fast-food restaurant near Rome''s Spanish Steps, advocates for local, seasonal and traditionally produced food. Its proponents argue that it preserves biodiversity, supports small producers and revives culinary heritage. Detractors, however, characterise it as elitist, pointing out that artisanal products are often beyond the means of low-income households, for whom cheap, convenient food is a necessity rather than a choice.',null,null,null,'practice'),
  ('ai:ai-batch-09:54338bdea839','C2'::public.cefr_level,'reading','What has helped citizen science expand?',array['fewer scientists','new universities','government funding cuts','the spread of smartphones']::text[],'D','''...have expanded dramatically with the spread of smartphones.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Citizen science projects, in which members of the public contribute to research by collecting or analysing data, have expanded dramatically with the spread of smartphones. Volunteers classify galaxies, count birds and record the timing of spring flowering, generating datasets far larger than professional scientists could gather alone. Concerns about data quality persist, but studies indicate that with appropriate training and statistical correction, volunteer data can match professional standards. Participants, meanwhile, report greater scientific literacy and engagement.',null,null,null,'practice'),
  ('ai:ai-batch-09:028039345ae8','C2'::public.cefr_level,'reading','Under what conditions can volunteer data match professional standards?',array['never','only for bird counts','with training and statistical correction','only when paid']::text[],'C','''...with appropriate training and statistical correction, volunteer data can match professional standards.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Citizen science projects, in which members of the public contribute to research by collecting or analysing data, have expanded dramatically with the spread of smartphones. Volunteers classify galaxies, count birds and record the timing of spring flowering, generating datasets far larger than professional scientists could gather alone. Concerns about data quality persist, but studies indicate that with appropriate training and statistical correction, volunteer data can match professional standards. Participants, meanwhile, report greater scientific literacy and engagement.',null,null,null,'practice'),
  ('ai:ai-batch-09:4e60fccd7727','C2'::public.cefr_level,'reading','What do participants gain?',array['professional jobs','university degrees','payment','greater scientific literacy and engagement']::text[],'D','''Participants... report greater scientific literacy and engagement.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','Citizen science projects, in which members of the public contribute to research by collecting or analysing data, have expanded dramatically with the spread of smartphones. Volunteers classify galaxies, count birds and record the timing of spring flowering, generating datasets far larger than professional scientists could gather alone. Concerns about data quality persist, but studies indicate that with appropriate training and statistical correction, volunteer data can match professional standards. Participants, meanwhile, report greater scientific literacy and engagement.',null,null,null,'practice'),
  ('ai:ai-batch-09:fd49784405a4','C2'::public.cefr_level,'reading','What do advocates say the classics cultivate?',array['sporting ability','musical skill','analytical rigour','social status']::text[],'C','''...the subjects cultivate analytical rigour.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The study of Greek and Latin, once the cornerstone of an elite British education, has declined markedly in state schools. Advocates of the classics argue that the subjects cultivate analytical rigour, enrich understanding of English vocabulary and illuminate the foundations of Western thought. Critics counter that the curriculum has historically reinforced social hierarchies. Recent initiatives seek to reconcile these positions by introducing classical languages in state primary schools, presenting them as a resource for all rather than a marker of privilege.',null,null,null,'practice'),
  ('ai:ai-batch-09:cd254bf2faad','C2'::public.cefr_level,'reading','What criticism has been made of classics teaching?',array['It ignores grammar.','It has reinforced social hierarchies.','It is too easy.','It is only taught to adults.']::text[],'B','''...the curriculum has historically reinforced social hierarchies.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The study of Greek and Latin, once the cornerstone of an elite British education, has declined markedly in state schools. Advocates of the classics argue that the subjects cultivate analytical rigour, enrich understanding of English vocabulary and illuminate the foundations of Western thought. Critics counter that the curriculum has historically reinforced social hierarchies. Recent initiatives seek to reconcile these positions by introducing classical languages in state primary schools, presenting them as a resource for all rather than a marker of privilege.',null,null,null,'practice'),
  ('ai:ai-batch-09:b17b04a7d4ac','C2'::public.cefr_level,'reading','How do recent initiatives try to reconcile the debate?',array['by introducing classics in state primary schools','by abolishing classics','by making them compulsory at university','by teaching them online only']::text[],'A','''...introducing classical languages in state primary schools.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-09','The study of Greek and Latin, once the cornerstone of an elite British education, has declined markedly in state schools. Advocates of the classics argue that the subjects cultivate analytical rigour, enrich understanding of English vocabulary and illuminate the foundations of Western thought. Critics counter that the curriculum has historically reinforced social hierarchies. Recent initiatives seek to reconcile these positions by introducing classical languages in state primary schools, presenting them as a resource for all rather than a marker of privilege.',null,null,null,'practice'),
  ('ai:ai-batch-09:a930c0fdb143','C2'::public.cefr_level,'vocabulary','The proposal was ___ by the board without discussion.',array['rubbed out','rubber-stamped','stamped out','rubber-necked']::text[],'B','Rubber-stamped = approved automatically.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-09',null,null,null,null,'practice'),
